SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(7*10^9);Alarm(500);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");root:="work/deg10/continuation_20261031b/C48/";X:=MDX1(48,GF(5));C:=Curve(X);F0,mp:=AlgorithmicFunctionField(FunctionField(C));F:=RationalExtensionRepresentation(F0);j:=F!mp(jInvariantMap(X));p2:=Places(F,2);p4:=Places(F,4);assert #p2 eq 12 and #p4 eq 68;print "D31B_C48_SMALL_CUSP_PLACES_READY",#p2,#p4,Cputime(tt);pairs:=[[p:p in p2|-Valuation(j,p)eq 2],[p:p in p4|-Valuation(j,p)eq 1]];assert &and[#ps eq 2:ps in pairs];OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);
function ER(v)return [[Integers()!a:a in Coefficients(Numerator(v))],[Integers()!a:a in Coefficients(Denominator(v))]];end function;function EF(v)return[ER(a):a in Eltseq(F!v)];end function;
function PD(p)return[*Degree(p),Order(Ideal(p))eq OF select 1 else 0,[EF(z):z in Basis(Ideal(p))]*];end function;
ps:=pairs;ds:=[12*(Divisor(pp[1])-Divisor(pp[2])):pp in ps];obs:=[* *];
for i in[1,2]do rows:=[* *];for n in[1,2,3,4]do B:=n*ds[i];bs:=Basis(B);h:=#bs;assert h in[0,1];fn:=[];if h eq 1 then b:=bs[1];IB,JB:=Ideals(B);assert IB*(b*OF)eq ideal<OF|1>and JB*(b*OI)eq ideal<OI|1>;fn:=EF(b);end if;Append(~rows,[*n,h,fn*]);print "D31B_C48_CUSP_CORRECTION_ORDER",i,n,h,Cputime(tt);if h eq 1 then break;end if;end for;Append(~obs,rows);end for;
Write(root cat "cusp_corrections_v2.m",Sprint([*[[PD(p):p in pp]:pp in ps],obs*]):Overwrite:=true);print "D31B_C48_CUSP_CORRECTIONS_COMPLETE",Cputime(tt);quit;
